REFERENCE_THRESHOLD = 0.9

ref_vectors = {
    name: v.transform([ref])
    for name, ref in REFERENCES.items()
}


def check_not_reference(text, case_name):
    if case_name not in ref_vectors:
        return 1

    text = re.sub(r"<br\s*/?>", " ", str(text or ""))
    text = re.sub(r"\s+", " ", text).strip()

    similarity = (
        v.transform([text]) @ ref_vectors[case_name].T
    ).toarray()[0, 0]

    return int(similarity < REFERENCE_THRESHOLD)